	h.db.Model(&MealRecord{}).Where("elderly_id = ? AND settlement_id IS NULL", e.ID).Count(&unsettled)
	c.JSON(200, gin.H{
		"message": fmt.Sprintf("资格记录已删除；已封账餐次 %d 笔保持原结果，未结算餐次 %d 笔请执行重新计算",
			settled, unsettled),
	})
}

